% Furye Transformatsiyasi (FFT) va Spektral tahlil
Fs = 1000;
t = 0:1/Fs:1-1/Fs;
x = sin(2*pi*50*t) + 0.7*sin(2*pi*150*t);

N = length(x);
X = fft(x);
A = abs(X)/N * 2;
f = (0:N/2) * (Fs/N);

figure;
subplot(2,1,1); plot(t(1:200), x(1:200)); title('Vaqt domeni (50 Hz + 150 Hz)'); grid on;
subplot(2,1,2); plot(f, A(1:N/2+1)); title('Amplituda spektri (FFT)'); xlim([0 300]); grid on;

%% 6) Vaqt sohasiga qaytarish
x_filtered = ifft(X_filtered);
%% 7) Natijalarni chiqarish
figure;
subplot(3,1,1)
plot(t, x)
title('Asl signal (vaqt sohasida)')
xlabel('t (s)'); ylabel('x(t)'); grid on;
subplot(3,1,2)
plot(f, A)
xlim([0 300])
title('Amplituda spektri')
xlabel('Chastota (Hz)'); ylabel('|X(f)|'); grid on;
subplot(3,1,3)
plot(f, phi)
xlim([0 300])
title('Faza spektri')
xlabel('Chastota (Hz)'); ylabel('\phi(f)'); grid on;
figure;
subplot(2,1,1)
plot(f, abs(X))
xlim([0 300])
title('Filtrlashdan oldingi spektr'); grid on;
subplot(2,1,2)
plot(f, abs(X_filtered))
xlim([0 300])
title('Filtrlashdan keyingi spektr'); grid on;
figure;
plot(t, x_filtered)
title('Filtrlangan signal (vaqt sohasida)')
xlabel('t (s)'); ylabel('x\_filtered(t)'); grid on;
